        "shadow": "none",
        "border-color": "{border}",
        "material": null
      },
      "inverse": {
        "background": "{inverse}",
        "border-color": "{border}",
        "material": null,
        "shadow": "0 4px 6px -1px oklch(0 0 0 / 0.1), 0 2px 4px -2px oklch(0 0 0 / 0.1)"
